    const checks: checks.$ZodCheck<never>[] = inst._zod.traits.has("$ZodCheck")
      ? [inst as any, ...(defChecks ?? [])]
      : defChecks?.length
        ? [...defChecks]
        : [];

    for (const ch of checks) {
      for (const fn of ch._zod.onattach) {
        fn(inst);
      }
    }

    if (checks.length === 0) {
      // deferred initializer inst._zod.parse is not yet defined
      inst._zod.deferred ??= [];
      inst._zod.deferred?.push(() => {
        inst._zod.run = inst._zod.parse;
      });
    } else {
      const runChecks = (
        payload: ParsePayload,
        checks: checks.$ZodCheck<never>[],
        ctx?: ParseContextInternal | undefined
      ): util.MaybeAsync<ParsePayload> => {
        if (payload.memo) return payload;

        let isAborted = util.aborted(payload);

        let asyncResult!: Promise<unknown> | undefined;
        for (const ch of checks) {
          if (ch._zod.def.when) {
            if (util.explicitlyAborted(payload)) continue;
            const shouldRun = ch._zod.def.when(payload);
            if (!shouldRun) continue;
          } else if (isAborted) {
            continue;
          }
          const currLen = payload.issues.length;
          const _ = ch._zod.check(payload as any) as any as ParsePayload;

          if (_ instanceof Promise && ctx?.async === false) {
            throw new core.$ZodAsyncError();
          }
          if (asyncResult || _ instanceof Promise) {
            asyncResult = (asyncResult ?? Promise.resolve()).then(async () => {
              await _;
              const nextLen = payload.issues.length;
              if (nextLen === currLen) return;
              util.attachSchema(payload.issues, currLen, inst);
              if (!isAborted) isAborted = util.aborted(payload, currLen);
            });
          } else {
            const nextLen = payload.issues.length;
            if (nextLen === currLen) continue;
            util.attachSchema(payload.issues, currLen, inst);
            if (!isAborted) isAborted = util.aborted(payload, currLen);
          }
        }

        if (asyncResult) {
          return asyncResult.then(() => {
            return payload;
          });
        }
        return payload;
      };

      const handleCanaryResult = (canary: ParsePayload, payload: ParsePayload, ctx: ParseContextInternal) => {
        // abort if the canary is aborted
        if (util.aborted(canary)) {
          canary.aborted = true;
          return canary;
        }

        // run checks first, then
        const checkResult = runChecks(payload, checks, ctx);
        if (checkResult instanceof Promise) {
          if (ctx.async === false) throw new core.$ZodAsyncError();
          return checkResult.then((checkResult) => inst._zod.parse(checkResult, ctx));
        }
        return inst._zod.parse(checkResult, ctx);
      };

      inst._zod.run = (payload, ctx) => {
        if (ctx.skipChecks) {
          return inst._zod.parse(payload, ctx);
        }
        if (ctx.direction === "backward") {
          // run canary initial pass (no checks)
          const canary = inst._zod.parse({ value: payload.value, issues: [] }, { ...ctx, skipChecks: true });

          if (canary instanceof Promise) {
            return canary.then((canary) => {
              return handleCanaryResult(canary, payload, ctx);
            });
          }

          return handleCanaryResult(canary, payload, ctx);
        }

        // forward
        const result = inst._zod.parse(payload, ctx);
        if (result instanceof Promise) {
          if (ctx.async === false) throw new core.$ZodAsyncError();
          return result.then((result) => runChecks(result, checks, ctx));
        }

        return runChecks(result, checks, ctx);
      };
    }
  },
  {
    // Wrappers extend this by installing a richer factory over it; reading it eagerly would defeat the laziness.
    get "~standard"(): StandardSchemaV1.Props<any, any> {
      return util.hide(this, "~standard", standardProps(this));
    },
    set "~standard"(value: StandardSchemaV1.Props<any, any>) {
      util.own(this, "~standard", value);
    },
  }
);

function handleCatchResult(payload: ParsePayload, result: ParsePayload, def: $ZodCatchDef, ctx: ParseContextInternal) {
  if (!result.issues.length) {
    payload.value = result.value;
    // The value carries up, so the flag describing it has to carry with it: a back-edge into a node still being parsed must not be frozen by an enclosing readonly, and its checks belong to the node itself. Guarded so the ordinary case adds no own property.
    if (result.memo) payload.memo = true;
    return payload;
  }

  // Spread the inner's own payload, not ours: `value` has to stay the input the catch was handed, and the inner ran on a payload of its own so its issues are already private to this call.
  payload.value = def.catchValue({
    ...result,
    value: payload.value,
    error: {
      issues: result.issues.map((iss) => util.finalizeIssue(iss, ctx, core.config())),
    },
    input: payload.value,
  });
  return payload;
}

inst._zod.parse = (payload, ctx) => {
  if (ctx.direction === "backward") {
    return def.innerType._zod.run(payload, ctx);
  }

  // Forward direction (decode): apply defaults for undefined input
  if (payload.value === undefined) {
    payload.value = def.defaultValue;
    /**
     * $ZodDefault returns the default value immediately in forward direction.
     * It doesn't pass the default value into the validator ("prefault"). There's no reason to pass the default value through validation. The validity of the default is enforced by TypeScript statically. Otherwise, it's the responsibility of the user to ensure the default is valid. In the case of pipes with divergent in/out types, you can specify the default on the `in` schema of your ZodPipe to set a "prefault" for the pipe.   */
    return payload;
  }
  // Forward direction: continue with default handling
  const result = def.innerType._zod.run(payload, ctx);
  if (result instanceof Promise) {
    return result.then((result) => handleDefaultResult(result, def));
  }
  return handleDefaultResult(result, def);
};

inst._zod.parse = (payload, _ctx) => {
  if (_ctx.direction === "backward") {
    throw new core.$ZodEncodeError(inst.constructor.name);
  }

  (payload as core.$RefinementCtx).addIssue = (issue) => {
    if (typeof issue === "string") {
      payload.issues.push(util.issue(issue, payload.value, def));
    } else {
      // for Zod 3 backwards compatibility
      const _issue = issue as any;

      if (_issue.fatal) _issue.continue = false;
      _issue.code ??= "custom";
      if (!("input" in _issue)) _issue.input = payload.value;
      _issue.inst ??= inst;
      // _issue.continue ??= true;
      payload.issues.push(util.issue(_issue));
    }
  };

  const output = def.transform(payload.value, payload);
  if (output instanceof Promise) {
    return output.then((output) => {
      payload.value = output;
      return payload;
    });
  }
  payload.value = output;
  return payload;
};

inst._zod.run = (payload, ctx) => {
  if (ctx.skipChecks) {
    return inst._zod.parse(payload, ctx);
  }
  if (ctx.direction === "backward") {
    // run canary initial pass (no checks)
    const canary = inst._zod.parse({ value: payload.value, issues: [] }, { ...ctx, skipChecks: true });

    if (canary instanceof Promise) {
      return canary.then((canary) => {
        return handleCanaryResult(canary, payload, ctx);
      });
    }

    return handleCanaryResult(canary, payload, ctx);
  }

  // forward
  const result = inst._zod.parse(payload, ctx);
  if (result instanceof Promise) {
    if (ctx.async === false) throw new core.$ZodAsyncError();
    return result.then((result) => runChecks(result, checks, ctx));
  }

  return runChecks(result, checks, ctx);
};

export const promiseProcessor: Processor<schemas.$ZodPromise> = (schema, ctx, _json, params) => {
  const def = schema._zod.def as schemas.$ZodPromiseDef;
  processSchema(def.innerType, ctx as any, params);
  const seen = ctx.seen.get(schema)!;
  seen.ref = def.innerType;
};

async safeParseAsync(data, params) {
  return parse.safeParseAsync(this, data, params);
},

validate(data, params) {
  return parse.validate(this, data, params);
},

safeParseAsync(data, params) {
  return parse.safeParseAsync(this, data, params);
},

export function standardProps(inst: $ZodType): StandardSchemaV1.Props<any, any> {
  return {
    validate: (value: unknown) => {
      const ctx: ParseContextInternal = { async: false };
      try {
        const r = inst._zod.run({ value, issues: [] }, ctx);
        if (!(r instanceof Promise)) return toStandardResult(r, ctx);
      } catch (_) {}
      // async function so a synchronously throwing check rejects instead of escaping validate
      return validateAsync(inst, value);
    },
    vendor: "zod",
    version: 1 as const,
  };
}

const runChecks = (
  payload: ParsePayload,
  checks: checks.$ZodCheck<never>[],
  ctx?: ParseContextInternal | undefined
): util.MaybeAsync<ParsePayload> => {
  if (payload.memo) return payload;

  let isAborted = util.aborted(payload);

  let asyncResult!: Promise<unknown> | undefined;
  for (const ch of checks) {
    if (ch._zod.def.when) {
      if (util.explicitlyAborted(payload)) continue;
      const shouldRun = ch._zod.def.when(payload);
      if (!shouldRun) continue;
    } else if (isAborted) {
      continue;
    }
    const currLen = payload.issues.length;
    const _ = ch._zod.check(payload as any) as any as ParsePayload;

    if (_ instanceof Promise && ctx?.async === false) {
      throw new core.$ZodAsyncError();
    }
    if (asyncResult || _ instanceof Promise) {
      asyncResult = (asyncResult ?? Promise.resolve()).then(async () => {
        await _;
        const nextLen = payload.issues.length;
        if (nextLen === currLen) return;
        util.attachSchema(payload.issues, currLen, inst);
        if (!isAborted) isAborted = util.aborted(payload, currLen);
      });
    } else {
      const nextLen = payload.issues.length;
      if (nextLen === currLen) continue;
      util.attachSchema(payload.issues, currLen, inst);
      if (!isAborted) isAborted = util.aborted(payload, currLen);
    }
  }

  if (asyncResult) {
    return asyncResult.then(() => {
      return payload;
    });
  }
  return payload;
};

inst._zod.parse = (payload, _ctx) => {
  const input = payload.value;
  if (typeof input === "undefined") return payload;
  payload.issues.push({
    expected: "undefined",
    code: "invalid_type",

    input,
    inst,
  });
  return payload;
};

function failure(Err: $ZodErrorClass, issues: errors.$ZodRawIssue[], ctx: schemas.ParseContextInternal): any {
  let error: errors.$ZodError | undefined;
  return {
    success: false,
    get error() {
      if (!error) {
        error = new Err(issues.map((iss) => util.finalizeIssue(iss, ctx, core.config())));
        // finalizeIssue drops `input`, so the built error holds nothing; keeping the raw issues past this point pins the parsed value for the life of the result
        issues = undefined as any;
        ctx = undefined as any;
      }
      return error;
    },
    set error(e: errors.$ZodError) {
      error = e;
      // a replacement makes the getter's branch unreachable, so the captures have to go here too
      issues = undefined as any;
      ctx = undefined as any;
    },
  };
}

inst._zod.parse = (payload, ctx) => {
  if (ctx.direction === "backward") {
    const right = def.out._zod.run(payload, ctx);
    if (right instanceof Promise) {
      return right.then((right) => handlePipeResult(right, def.in, ctx));
    }
    return handlePipeResult(right, def.in, ctx);
  }

  const left = def.in._zod.run(payload, ctx);
  if (left instanceof Promise) {
    return left.then((left) => handlePipeResult(left, def.out, ctx));
  }
  return handlePipeResult(left, def.out, ctx);
};

inst._zod.parse = (payload, ctx) => {
  const input = payload.value;
  const left = def.left._zod.run({ value: input, issues: [] }, ctx);
  const right = def.right._zod.run({ value: input, issues: [] }, ctx);
  const async = left instanceof Promise || right instanceof Promise;

  if (async) {
    return Promise.all([left, right]).then(([left, right]) => {
      return handleIntersectionResults(payload, left, right);
    });
  }

  return handleIntersectionResults(payload, left, right);
};

inst._zod.parse = (payload, _ctx) => {
  const input = payload.value;
  if (typeof input === "symbol") return payload;
  payload.issues.push({
    expected: "symbol",
    code: "invalid_type",

    input,
    inst,
  });
  return payload;
};

parseAsync(data, params) {
  return parse.parseAsync(this, data, params, { callee: this.parseAsync });
},

