      case "invalid_key":
        return `Սխալ բանալի ${withDefiniteArticle(issue.origin)}-ում`;
      case "invalid_union":
        return "Սխալ մուտքագրում";
      case "invalid_element":
        return `Սխալ արժեք ${withDefiniteArticle(issue.origin)}-ում`;
      default:
        return `Սխալ մուտքագրում`;
    }
  };
};

