maxValue: (inst) => {
  const { maximum, exclusiveMaximum } = processors.aggregateChecks<number>(inst);
  return Math.min(maximum ?? Number.POSITIVE_INFINITY, exclusiveMaximum ?? Number.POSITIVE_INFINITY);
