    object: (s) => schemas.partial(s as schemas.ZodMiniObject),
    // See `classic/deep-partial.ts`.
    union: (s) => {
      const def = s._zod.def as core.$ZodDiscriminatedUnionDef;
      return def.discriminator === undefined ? s : schemas.union(def.options as schemas.ZodMiniType[]);
    },
  }) as unknown as DeepPartial<T>;
}

export function partial(schema: ZodMiniObject | ZodMiniTuple, mask?: object) {
  const def = schema._zod.def;
  if (def.type !== "tuple") return util.partial(ZodMiniOptional, schema as ZodMiniObject, mask);
  // a refinement was authored against the full arity; partialing would run it on a shorter array
  if (def.checks?.length) throw new Error(".partial() cannot be used on tuple schemas containing refinements");
  return util.clone(schema, {
    ...def,
    items: def.items.map((item) => new ZodMiniOptional({ type: "optional", innerType: item as core.$ZodType })),
  });
}

function undeclaredConstraint(member: JSONSchema.ObjectSchema): JSONSchema.BaseSchema | null {
  const extra = member.additionalProperties;
  if (extra === undefined || extra === false || typeof extra !== "object" || extra === null) return null;
  return Object.keys(extra).length ? (extra as JSONSchema.BaseSchema) : null;
}

inst._zod.parse = (payload, ctx) => {
  if (payload.value === undefined) {
    // Only the top rung substitutes a value for absence; everything else leaves it intact, which is what .optional() means.
    if (def.innerType._zod.optin !== "defaulted") return payload;
    // Its own payload, for the same reason $ZodCatch gets one: a pipe forwards an unrecognized key through the caller's issues array, and this must not read that as the substituting schema failing and drop it.
    const result = def.innerType._zod.run({ value: payload.value, issues: [] }, ctx);
    if (result instanceof Promise) return result.then((result) => handleOptionalResult(payload, result));
    return handleOptionalResult(payload, result);
  }
  return def.innerType._zod.run(payload, ctx);
};

optional() {
  return optional(this);
},

export function isRecursiveSchema(inst: $ZodType): boolean {
  // z.compile never parses, so nothing would ever resolve a lazy for it; it runs once and already treats a throw here as recursive
  return isRecursive(inst, new Set(), true) !== NONE;
}

export const ZodObject: core.$constructor<ZodObject> = /*@__PURE__*/ core.$constructor<ZodObject>(
  "ZodObject",
  (inst, def) => {
    _ensureDefaultMemoizer();
    core.$ZodObjectJIT.init(inst, def);
    ZodType.init(inst, def);
    inst._zod.processJSONSchema = (ctx, json, params) => processors.objectProcessor(inst, ctx, json, params);

    util.installLazyProp(inst, "shape", (self) => self._zod.def.shape, false);
