function containsRef(value: unknown): boolean {
  if (typeof value !== "object" || value === null) return false;
  if (Array.isArray(value)) return value.some(containsRef);
  if (typeof (value as any).$ref === "string") return true;
  return Object.entries(value).some(([key, sub]) => {
    if (SCHEMA_KEYWORDS.has(key)) return containsRef(sub);
    if (!SCHEMA_MAP_KEYWORDS.has(key) || typeof sub !== "object" || sub === null) return false;
    return Object.values(sub).some(containsRef);
  });
}

const extractToDef = (entry: [schemas.$ZodType<unknown, unknown>, Seen]): void => {
  // if the schema is already a reference, do not extract it
  if (entry[1].schema.$ref) {
    return;
  }
  const seen = entry[1];
  const { ref, defId } = makeURI(entry);

  seen.def = { ...seen.schema };
  // defId won't be set if the schema is a reference to an external schema or if the schema is the root schema
  if (defId) seen.defId = defId;
  // wipe away all properties except $ref
  const schema = seen.schema;
  for (const key in schema) {
    delete schema[key];
  }
  schema.$ref = ref;
};

